    <style>
        :root{--black:#0b0b0b;--ink:#11100f;--ivory:#f4f1ea;--gold:#c5a059;--gold-light:#d4af37;--red:#8b0000;--wine:#4c1013;--line:#5f4827}
        *{box-sizing:border-box}body{font-family:Montserrat,Arial,sans-serif;background:var(--black);color:var(--ivory);margin:0;min-height:100vh;background-image:linear-gradient(90deg,rgba(6,6,6,.92),rgba(6,6,6,.72)),url('/fondo.jpg');background-size:cover;background-position:center;background-attachment:fixed}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.08;background-image:radial-gradient(#d4af37 1px,transparent 1px);background-size:7px 7px;mix-blend-mode:screen}
        header{position:sticky;top:0;z-index:5;background:rgba(8,8,8,.94);border-bottom:1px solid var(--line);box-shadow:0 5px 24px #000b;padding:10px 5%;display:flex;align-items:center;justify-content:space-between;gap:20px}header .brand{display:flex;align-items:center;gap:13px;color:var(--ivory);text-decoration:none;font-family:Cinzel,serif;font-weight:700;letter-spacing:2px}header .brand img{width:58px;height:48px;object-fit:cover;object-position:center;border:1px solid var(--gold);border-radius:3px}nav{display:flex;align-items:center;gap:18px;font-size:12px;letter-spacing:1.5px;text-transform:uppercase}nav a{color:var(--ivory);text-decoration:none}nav a:hover{color:var(--gold-light)}nav form{display:inline}nav button{font-size:11px!important;width:auto!important;padding:6px 10px!important;background:transparent!important;color:var(--gold-light)!important;border:1px solid var(--line)!important}
        main{max-width:1080px;margin:42px auto;padding:0 22px}.hero{text-align:center;padding:20px 0 35px}.hero img{width:min(100%,430px);max-height:300px;object-fit:contain;filter:drop-shadow(0 9px 15px #000)}h1,h2,h3{font-family:Cinzel,Georgia,serif;letter-spacing:1px;color:var(--ivory)}h1{font-size:clamp(29px,5vw,48px);margin:10px 0}h2{color:var(--gold-light);font-size:22px}h3{font-size:16px;color:var(--gold)}.hero p,.muted{color:#c6bfb3;line-height:1.7}.card{background:linear-gradient(145deg,rgba(25,23,20,.95),rgba(10,10,10,.93));border:1px solid var(--line);border-radius:3px;padding:26px;margin:16px 0;box-shadow:0 12px 32px #0008}.card:before{content:"✦";float:right;color:var(--gold);font-size:15px}label{display:block;margin:12px 0 6px;font-weight:600;color:#d8c7a9;font-size:13px;letter-spacing:.4px}input,select,button{font:inherit;width:100%;padding:12px;border:1px solid #5d554b;border-radius:2px;box-sizing:border-box;background:#171614;color:var(--ivory)}input:focus,select:focus{outline:1px solid var(--gold-light);border-color:var(--gold-light)}button,.button{background:var(--red);color:var(--ivory);border:1px solid #b34b3e;cursor:pointer;text-decoration:none;display:inline-block;text-align:center;padding:13px;border-radius:2px;text-transform:uppercase;letter-spacing:1.4px;font-size:12px;font-weight:700}button:hover,.button:hover{background:#b22222;box-shadow:0 0 15px #8b000066}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.error{color:#ffaaa1;border-left:3px solid #b22222;padding-left:12px}.success{color:#e7c97e;border-left:3px solid var(--gold);padding-left:12px}.status{color:var(--gold-light);font-size:12px;text-transform:uppercase;letter-spacing:1px}.ornament{height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:25px 0}
        @media(max-width:620px){header{padding:8px 14px}header .brand span{display:none}nav{gap:8px;font-size:10px}main{margin:25px auto;padding:0 14px}.card{padding:18px}.hero img{max-height:245px}}
    </style>
